INSERT INTO ofertas_culturales (id_conocimiento, nombre, descripcion, categoria, municipio, departamento, etiquetas, relacion_afro, nota_relacion_afro, fuente_entidad, fuente_titulo, fecha_fuente, fuente_url, estado_verificacion, fecha_verificacion)
VALUES
  ('BCA-ATR-001', 'Malecón y Cristo Petrolero (Ciénaga Miramar)', 'Escultura de unos 26 m y 20 toneladas que emerge del agua de la ciénaga Miramar, frente a la refinería; se ilumina de noche. El malecón tiene un sendero peatonal empedrado con figuras metálicas y es ideal para caminar y ver el atardecer.', 'atractivo', 'Barrancabermeja', 'Santander', 'malecón | mirador | atardecer | paseo | fotografía | río magdalena | ciénaga miramar | zona:Centro – ciénaga Miramar | ninos:si | bano:ninguno | momento:atardecer | momento:noche | dia:ciudad_rio | tiempo:en el casco urbano | costo:Acceso libre', 'sin_relacion', NULL, 'El Tiempo', 'Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-un-viaje-inolvidable-a-orillas-del-magdalena-3486599', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-ATR-002', 'Museo peatonal de fauna nativa del río Yuma', 'Museo al aire libre con esculturas de animales de la región (pumas, iguanas, garzas, tortugas, chigüiros) del maestro Lombana. Recorrido a pie atractivo para niños y para observadores de aves.', 'atractivo', 'Barrancabermeja', 'Santander', 'niños | esculturas | fauna | aire libre | gratis | aves | zona:Avenida del Ferrocarril | ninos:si | bano:ninguno | momento:manana | momento:tarde | dia:ciudad_rio | tiempo:en el casco urbano | direccion:Avenida del Ferrocarril | costo:Acceso libre', 'sin_relacion', NULL, 'Alcaldía Distrital de Barrancabermeja', '¿Qué hay pa’ hacer?', DATE '2021-05-24', 'https://www.barrancabermeja.gov.co/publicaciones/1227/que-hay-pa-hacer/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-ATR-003', 'Parque a la Vida', 'Parque con juegos, zonas verdes, restaurantes y bares de cocina local e internacional (barrios Colombia y El Recreo). Punto de salida de la tradicional chiva rumbera.', 'atractivo', 'Barrancabermeja', 'Santander', 'parque | juegos infantiles | restaurantes | cena | familia | zona:Barrios Colombia y El Recreo | ninos:si | bano:ninguno | momento:tarde | momento:noche | dia:ciudad_rio | tiempo:en el casco urbano', 'sin_relacion', NULL, 'Alcaldía Distrital de Barrancabermeja / El Tiempo', '¿Qué hay pa’ hacer? · Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.barrancabermeja.gov.co/publicaciones/1227/que-hay-pa-hacer/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-ATR-004', 'Museo del Petróleo', 'Fundado en 1984. Recorre la historia de la extracción y refinación del petróleo con mapas, maquetas, fotografías, maquinaria antigua y salas interactivas (unas 450 piezas).', 'atractivo', 'Barrancabermeja', 'Santander', 'museo | historia | petróleo | educativo | bajo techo | zona:Barrancabermeja | ninos:si | bano:ninguno | momento:manana | dia:ciudad_rio | confirmar:Las fuentes no publican dirección ni horario: confirmar antes de ir.', 'sin_relacion', NULL, 'Alcaldía Distrital de Barrancabermeja / Turismo enColombia', '¿Qué hay pa’ hacer?', DATE '2021-05-24', 'https://www.barrancabermeja.gov.co/publicaciones/1227/que-hay-pa-hacer/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-ATR-005', 'Puente Guillermo Gaviria Correa (Barrancabermeja–Yondó)', 'Puente sobre el río Magdalena que une Santander con Antioquia; reconocido por sus atardeceres.', 'atractivo', 'Barrancabermeja', 'Santander', 'puente | atardecer | río magdalena | fotografía | zona:Río Magdalena | ninos:si | bano:ninguno | momento:atardecer | dia:ciudad_rio', 'sin_relacion', NULL, 'Weekend Santander', 'Barrancabermeja, la ciudad y el río', DATE '2023-12-21', 'https://weekendsantander.com/blog/barrancabermeja-santander-que-hacer/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-ATR-006', 'Corregimiento El Centro (primer pozo petrolero)', 'A unos 20 minutos en carro hacia el sur. Allí se perforó el primer pozo petrolero del país (La Cira-Infantas, 1918). Tiene restaurantes campestres con bocachico, bagre y cortes de res y cabro.', 'atractivo', 'Barrancabermeja', 'Santander', 'historia | petróleo | restaurante campestre | almuerzo | bocachico | zona:Sur del distrito | ninos:si | bano:ninguno | momento:mediodia | dia:cultura_afro | tiempo:20 min en carro', 'sin_relacion', NULL, 'El Tiempo', 'Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-un-viaje-inolvidable-a-orillas-del-magdalena-3486599', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-AFR-001', 'Paseo de la Cultura', 'Parque dedicado a la música de bandas pelayeras, la cumbia y el porro, con tres templetes y una estatua de mujer afrocolombiana. Sede del Festival Nacional de Bandas Folclóricas (abril) y de tradiciones como la Pollera Colorá, María Varilla, Arrancatetas y Vaca Vieja.', 'cultura_afro', 'Barrancabermeja', 'Santander', 'cultura | música | bandas | cumbia | estatua mujer afro | gratis | zona:Barrio Galán, Avenida 60 | ninos:si | bano:ninguno | momento:manana | momento:tarde | dia:ciudad_rio | tiempo:en el casco urbano | direccion:Barrio Galán, Avenida 60 | costo:Acceso libre', 'directa', 'Incluye una estatua de mujer afrocolombiana y homenajea músicas de raíz afro-caribe (cumbia, porro).', 'Weekend Santander / Alcaldía Distrital de Barrancabermeja', 'Barrancabermeja, la ciudad y el río · ¿Qué hay pa’ hacer?', DATE '2023-12-21', 'https://weekendsantander.com/blog/barrancabermeja-santander-que-hacer/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-AFR-002', 'Festival de Tamboras', 'Festival de tamboras y folclor colombiano que se realiza en marzo.', 'festival', 'Barrancabermeja', 'Santander', 'festival | tambora | música tradicional | marzo | zona:Barrancabermeja | ninos:si | bano:ninguno | momento:noche | confirmar:Confirmar fechas exactas de la edición del año.', 'directa', 'La tambora es una tradición musical de raíz afro del río Magdalena.', 'Turismo enColombia', 'Barrancabermeja: guía de turismo completa', NULL, 'https://turismo.encolombia.com/barrancabermeja/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-AFR-003', 'Festival Nacional de Bandas Folclóricas', 'Se realiza en abril en el Paseo de la Cultura; reconocido como patrimonio cultural y artístico de la Nación.', 'festival', 'Barrancabermeja', 'Santander', 'festival | bandas | abril | patrimonio | zona:Paseo de la Cultura | ninos:si | bano:ninguno | momento:noche', 'contextual', 'Las bandas pelayeras interpretan porro y cumbia, géneros de raíz afro-caribe.', 'Alcaldía Distrital de Barrancabermeja', '¿Qué hay pa’ hacer?', DATE '2021-05-24', 'https://www.barrancabermeja.gov.co/publicaciones/1227/que-hay-pa-hacer/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-AFR-004', 'Parque del Cacique Pipatón y Yarima', 'Monumento al cacique Pipatón (líder yariguí). En el parque hay comida típica y artesanías.', 'atractivo', 'Barrancabermeja', 'Santander', 'monumento | artesanías | comida típica | historia indígena | zona:Barrancabermeja | ninos:si | bano:ninguno | momento:tarde | dia:cultura_afro', 'sin_relacion', 'Patrimonio indígena yariguí; útil para contextualizar la diversidad étnica del territorio.', 'El Tiempo', 'Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-un-viaje-inolvidable-a-orillas-del-magdalena-3486599', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-NAT-001', 'Ciénaga San Silvestre', 'A unos 15 minutos al norte. Principal espejo de agua del Magdalena Medio y fuente del agua potable de la ciudad; hábitat del manatí antillano, chigüiros, babillas y unas 71 especies de aves. Tiene clubes náuticos, balnearios y restaurantes; se practican esquí acuático, jet ski y paseos en lancha.', 'naturaleza', 'Barrancabermeja', 'Santander', 'ciénaga | lancha | esquí acuático | aves | manatí | naturaleza | zona:Norte – San Silvestre | ninos:si | bano:no_recomendado | momento:manana | momento:tarde | dia:cienagas_agua | tiempo:15 min | seguridad:No bañarse en aguas abiertas de la ciénaga: es fuente de agua potable, hay babillas (en febrero de 2026 se trasladaron allí babillas adultas) y no hay salvavidas. En lancha, todos con chaleco salvavidas.', 'contextual', 'Territorio de pesca artesanal ribereña del Magdalena Medio.', 'El Tiempo / Weekend Santander / El Frente', 'Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-un-viaje-inolvidable-a-orillas-del-magdalena-3486599', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-NAT-002', 'Corregimiento El Llanito (pueblo de pescadores)', 'Pueblo de pescadores a unos 30 minutos del casco urbano, frente a la ciénaga. Murales, tejido de atarraya, paseos en chalupa hacia La Isla de los Mangos e Isla del Amor, y platos de bocachico frito o sudado y caldos de pescado. Los visitantes disfrutan el café viendo el atardecer sobre la ciénaga.', 'naturaleza', 'Barrancabermeja', 'Santander', 'pescadores | bocachico | almuerzo | chalupa | atardecer | murales | tinto al atardecer | zona:Norte – El Llanito | ninos:si | bano:no_recomendado | momento:mediodia | momento:atardecer | tinto:si | dia:cienagas_agua | tiempo:30 min | costo:Un plato de pescado ronda los $30.000 según reseñas (Tripadvisor) | seguridad:Disfrutar la ciénaga desde la orilla o en chalupa con chaleco; no es zona de baño para niños.', 'contextual', 'Cultura anfibia y de pesca artesanal ribereña del Magdalena Medio, con saberes compartidos por comunidades afro del río.', 'Alcaldía Distrital de Barrancabermeja / Tripadvisor', 'Corregimiento El Llanito · Opiniones sobre El Llanito', DATE '2020-11-05', 'https://www.barrancabermeja.gov.co/publicaciones/343/corregimiento-el-llanito/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-NAT-003', 'Ciénaga de San Rafael de Chucurí (paseo comunitario en chalupa)', 'A unos 40–45 minutos por el río desde el puerto Yuma. Un proyecto comunitario de pescadores ofrece recorridos por los caños para ver aves y micos, el contraste de aguas claras y negras, presenciar una faena de pesca y probar empanadas de bocachico seco.', 'naturaleza', 'Barrancabermeja', 'Santander', 'chalupa | turismo comunitario | pescadores | aves | micos | empanadas de bocachico | zona:Río Magdalena – puerto Yuma | ninos:si | bano:no_recomendado | momento:manana | dia:cultura_afro | tiempo:40–45 min en chalupa | seguridad:Chaleco salvavidas obligatorio para todos, en especial los niños. Consultar el nivel del río antes de salir. | confirmar:Confirmar operador, horario y tarifa en el puerto Yuma (terminal en remodelación según El Tiempo, 2025).', 'contextual', 'Turismo comunitario de pescadores ribereños; saberes de pesca y cocina de río.', 'El Tiempo / Weekend Santander', 'Barrancabermeja, un destino natural más allá del petróleo', DATE '2022-01-15', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-planes-turisticos-y-naturales-645045', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-NAT-004', 'Ruta de los micos (recorrido fluvial)', 'Recorrido en lancha desde el sector La Represa para ver micos aulladores rojos, nutrias y, a veces, manatíes.', 'naturaleza', 'Barrancabermeja', 'Santander', 'lancha | fauna | micos | nutrias | manatí | niños | zona:Sector La Represa | ninos:si | bano:no_recomendado | momento:manana | dia:cultura_afro | seguridad:Chaleco salvavidas para todos. | confirmar:Confirmar operador y horario de salida.', 'sin_relacion', NULL, 'El Tiempo', 'Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-un-viaje-inolvidable-a-orillas-del-magdalena-3486599', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-REC-001', 'CAFABA – Sede Recreacional José Joaquín Bohórquez', 'Centro recreativo natural de la Caja de Compensación Familiar de Barrancabermeja junto a la ciénaga San Silvestre, con piscina, actividades acuáticas y deportivas, restaurante y espacios para paseos en familia.', 'recreacion_acuatica', 'Barrancabermeja', 'Santander', 'piscina | niños | familia | bañarse | restaurante | san silvestre | zona:Vía a El Llanito, vereda San Silvestre | ninos:si | bano:piscina | momento:dia_completo | dia:cienagas_agua | tiempo:10–15 min | direccion:Vía El Llanito, vereda San Silvestre | horario:Mar–vie 8:00–16:30 (piscina 9:00–16:00); sáb, dom y festivos 8:00–17:00 (piscina 9:00–16:30). Lunes cerrado (si el lunes es festivo, cierra el martes). | contacto:PBX (607) 611 8230 · Cel. 317 423 0387 · sederecreacional@cafaba.com.co | confirmar:La página no publica tarifas ni si admite no afiliados: llamar antes de ir.', 'sin_relacion', NULL, 'CAFABA', 'Sede recreacional José Joaquín Bohórquez', DATE '2026-10-15', 'https://www.cafaba.com.co/recreacion/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-REC-002', 'Club Miramar – Sede campestre', 'Sede campestre a unos 20 minutos, sobre la ciénaga San Silvestre, con juegos acuáticos e infantiles, paseos en lancha, servicio de comida y parapente.', 'recreacion_acuatica', 'Barrancabermeja', 'Santander', 'club | juegos acuáticos | niños | lancha | comida | zona:Norte – San Silvestre | ninos:si | bano:piscina | momento:dia_completo | dia:cienagas_agua | tiempo:20 min | confirmar:Es un club: confirmar si permite el ingreso de visitantes no socios y la tarifa.', 'sin_relacion', NULL, 'Alcaldía Distrital de Barrancabermeja', '¿Qué hay pa’ hacer?', DATE '2021-05-24', 'https://www.barrancabermeja.gov.co/publicaciones/1227/que-hay-pa-hacer/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-REC-003', 'Club Infantas', 'Club con piscinas olímpica y semiolímpica, toboganes, zonas de juegos infantiles, restaurantes, canchas, patinódromo y gimnasio.', 'recreacion_acuatica', 'Barrancabermeja', 'Santander', 'club | piscina | toboganes | niños | bañarse | zona:Barrancabermeja | ninos:si | bano:piscina | momento:dia_completo | dia:cienagas_agua | confirmar:Es un club: confirmar condiciones de ingreso para visitantes.', 'sin_relacion', NULL, 'Alcaldía Distrital de Barrancabermeja', '¿Qué hay pa’ hacer?', DATE '2021-05-24', 'https://www.barrancabermeja.gov.co/publicaciones/1227/que-hay-pa-hacer/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-REC-004', 'Parque del Agua de Barrancabermeja', 'Parque público con piscina de olas (la más grande del país según la Alcaldía), piscina infantil y zonas de juegos, a cargo de INDERBA. La obra estuvo años en construcción y suspendida; en abril de 2025 seguía en intervención.', 'recreacion_acuatica', 'Barrancabermeja', 'Santander', 'parque acuático | piscina de olas | piscina infantil | niños | zona:Barrancabermeja | ninos:si | bano:parque_acuatico | momento:dia_completo | confirmar:No encontramos confirmación de su apertura al público: verificar con INDERBA antes de planear la visita.', 'sin_relacion', NULL, 'Semana / Telepetróleo / El Tiempo', 'Santander logró sacar del limbo una emblemática construcción en Barrancabermeja', DATE '2025-04-09', 'https://www.semana.com/mejor-colombia/articulo/esta-obra-que-barrancabermeja-daba-por-perdida-volvio-a-la-vida-cuanto-le-costo-a-santander-rescatarla/202547/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('SVC-EXC-001', 'Piscinas naturales de San Vicente de Chucurí (vereda Cantarranas)', 'Pozos naturales en una finca a 8 km (unos 15 min) del casco urbano de San Vicente de Chucurí, por la vía hacia la vereda Cantarranas. Clima de 20 a 27 °C; el plan es bañarse todo el día. El cuidandero ofrece comida (precio a convenir).', 'excursion', 'San Vicente de Chucurí', 'Santander', 'pozo natural | bañarse | paseo de olla | naturaleza | excursión | zona:San Vicente de Chucurí | ninos:si | bano:pozo_natural | momento:dia_completo | dia:excursion | tiempo:excursión de día completo por carretera; calcular el trayecto antes de salir | costo:$2.000 por persona (dato de 2019) | seguridad:Pozo natural sin salvavidas: niños siempre al alcance de un adulto y con flotador o chaleco; no entrar si llovió y baja creciente. | confirmar:Fuente de 2019: confirmar que sigue abierto, el costo y la profundidad.', 'sin_relacion', NULL, 'Senderismo Colombia', 'Piscinas naturales en San Vicente de Chucurí', DATE '2019-06-21', 'https://senderismocol.com/ecoturismo/santander/piscinas-naturales/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('SVC-EXC-002', 'Cueva de los Aviones (San Vicente de Chucurí)', 'Recorrido entre toboganes naturales, cascadas, pozos y cuevas en la vereda Cantarranas, con torrentismo. Dificultad media; se recomienda operador certificado y calzado con buen agarre.', 'excursion', 'San Vicente de Chucurí', 'Santander', 'aventura | cascadas | pozos | torrentismo | guía | zona:San Vicente de Chucurí | ninos:no | bano:pozo_natural | momento:dia_completo | dia:excursion | seguridad:Dificultad media: no recomendado para niños pequeños. Ir solo con guía certificado.', 'sin_relacion', NULL, 'El Tiempo', 'Barrancabermeja, un destino natural más allá del petróleo', DATE '2022-01-15', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-planes-turisticos-y-naturales-645045', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BET-EXC-001', 'Parque Acuático Los Trinitarios (Comfenalco Santander)', 'Parque acuático en Betulia, frente al embalse de Topocoro, inaugurado en abril de 2026; el más grande del oriente colombiano según sus operadores. Tiene la zona Aquakids para los más pequeños con juegos interactivos, chorros y toboganes.', 'excursion', 'Betulia', 'Santander', 'parque acuático | niños | toboganes | aquakids | topocoro | excursión | zona:Betulia – embalse de Topocoro | ninos:si | bano:parque_acuatico | momento:dia_completo | dia:excursion | tiempo:menos de 90 min por carretera | confirmar:Las fuentes no publican tarifas ni horarios: consultar en comfenalcosantander.com.co.', 'sin_relacion', NULL, 'Vanguardia / Metropolitano', 'Conozca las atracciones del Parque Acuático Los Trinitarios', DATE '2026-04-25', 'https://www.vanguardia.com/santander/2026/04/25/conozca-las-atracciones-del-parque-acuatico-los-trinitarios-el-mas-grande-del-oriente-colombiano/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BET-EXC-002', 'Embalse de Topocoro', 'Embalse con islas y vegetación; kayak, paddle board, jet ski, wakeboard y lanchas hacia cascadas; cabañas, glamping y restaurantes.', 'excursion', 'Betulia', 'Santander', 'embalse | lancha | kayak | cascadas | excursión | zona:Betulia | ninos:si | bano:no_recomendado | momento:tarde | dia:excursion | seguridad:Actividades acuáticas siempre con chaleco y con operador.', 'sin_relacion', NULL, 'El Tiempo', 'Barrancabermeja, un viaje inolvidable a orillas del Magdalena', DATE '2025-09-02', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-un-viaje-inolvidable-a-orillas-del-magdalena-3486599', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-GAS-001', 'Cocina ribereña de Barrancabermeja', 'Platos típicos: bocachico y bagre (frito, sudado o frito-sudado), cachama, doncella, sancocho, cazuela, patacones con suero, arroz con coco, tamales de arroz, bollos y dulces de mango, fríjol y ñame.', 'gastronomia', 'Barrancabermeja', 'Santander', 'gastronomía | bocachico | bagre | sancocho | arroz con coco | dulces | zona:Barrancabermeja | ninos:si | bano:ninguno | momento:mediodia', 'contextual', 'Cocina de río con técnicas y productos compartidos con comunidades afro del Magdalena (arroz con coco, bollos, pescado de río).', 'Weekend Santander / El Tiempo', 'Barrancabermeja, la ciudad y el río', DATE '2023-12-21', 'https://weekendsantander.com/blog/barrancabermeja-santander-que-hacer/', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-GAS-002', 'Muelle Comida – Mirador', 'Punto de comida y mirador junto al río: bocachico frito-sudado, arroz con coco y patacones con suero.', 'gastronomia', 'Barrancabermeja', 'Santander', 'almuerzo | mirador | río | bocachico | arroz con coco | zona:Ribera del río Magdalena | ninos:si | bano:ninguno | momento:mediodia | dia:ciudad_rio | confirmar:La fuente no da dirección exacta.', 'contextual', NULL, 'Weekend Santander', 'Barrancabermeja, la ciudad y el río', DATE '2023-12-21', 'https://weekendsantander.com/blog/barrancabermeja-santander-que-hacer/', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-GAS-003', 'Restaurante Isla de los Mangos (El Llanito)', 'Restaurante de cocina caribeña/latina cerca de El Llanito; calificación 3,7/5 con 3 reseñas en Tripadvisor.', 'gastronomia', 'Barrancabermeja', 'Santander', 'almuerzo | pescado | el llanito | zona:Norte – El Llanito | ninos:si | bano:ninguno | momento:mediodia | dia:cienagas_agua', 'sin_relacion', NULL, 'Tripadvisor', 'El Llanito – restaurantes cercanos', DATE '2026-10-15', 'https://www.tripadvisor.com/Attraction_Review-g1594789-d10604777-Reviews-El_Llanito-Barrancabermeja_Santander_Department.html', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-GAS-004', 'Estadero Puerto Libre de la Familia Polanco (El Llanito)', 'Estadero familiar listado junto a El Llanito (sin calificación publicada).', 'gastronomia', 'Barrancabermeja', 'Santander', 'almuerzo | estadero | el llanito | familia | zona:Norte – El Llanito | ninos:si | bano:ninguno | momento:mediodia | dia:cienagas_agua', 'sin_relacion', NULL, 'Tripadvisor', 'El Llanito – restaurantes cercanos', DATE '2026-10-15', 'https://www.tripadvisor.com/Attraction_Review-g1594789-d10604777-Reviews-El_Llanito-Barrancabermeja_Santander_Department.html', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-GAS-005', 'La Cazuela', 'Restaurante recomendado para platos regionales, en especial la cazuela de bagre.', 'gastronomia', 'Barrancabermeja', 'Santander', 'almuerzo | cena | cazuela de bagre | comida regional | zona:Barrancabermeja | ninos:si | bano:ninguno | momento:mediodia | momento:noche | dia:ciudad_rio | confirmar:Fuente de 2022: confirmar que sigue abierto y su dirección.', 'sin_relacion', NULL, 'El Tiempo', 'Barrancabermeja, un destino natural más allá del petróleo', DATE '2022-01-15', 'https://www.eltiempo.com/vida/viajar/barrancabermeja-planes-turisticos-y-naturales-645045', 'requiere_confirmacion', DATE '2026-10-15'),
  ('BCA-CAF-001', 'Criba 18 Café', 'Café de especialidad con desayunos; 4,5/5 en Tripadvisor ("buen café", "un lugar único"). Carta: americano, espresso doble, café campesino con panela, clavo y canela, carajillo, latte y capuchinos.', 'cafe', 'Barrancabermeja', 'Santander', 'tinto | café | desayuno | café de especialidad | café campesino | zona:Centro | ninos:si | bano:ninguno | momento:manana | momento:tarde | tinto:si | dia:ciudad_rio | direccion:Carrera 24 # 49-64 | costo:Americano 12 oz ≈ $7.600 · café campesino ≈ $9.600 (precios en Rappi) | confirmar:El horario publicado en Rappi es el de domicilios; confirmar el horario del local.', 'sin_relacion', NULL, 'Tripadvisor / Rappi', 'Criba 18 Café, Barrancabermeja', DATE '2026-10-15', 'https://www.tripadvisor.com/Restaurant_Review-g1594789-d25278366-Reviews-Criba_18_Cafe-Barrancabermeja_Santander_Department.html', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-CAF-002', 'Maravillas del Café', 'Café-restaurante familiar cerca del Parque a la Vida, con gran variedad de cafés, platos de sal y postres (waffles, brownie con helado). 4,2/5 con 397 reseñas; tarde de fin de semana muy concurrida, conviene reservar.', 'cafe', 'Barrancabermeja', 'Santander', 'tinto | café | postres | familia | cena | zona:Cerca del Parque a la Vida | ninos:si | bano:ninguno | momento:tarde | momento:noche | tinto:si | dia:ciudad_rio | direccion:Carrera 25, cerca del Parque a la Vida | costo:Alrededor de $20.000–30.000 por persona según reseñas | contacto:+57 302 366 9800', 'sin_relacion', NULL, 'Carta.menu (reseñas agregadas)', 'Maravillas del Café en Barrancabermeja', DATE '2026-10-15', 'https://carta.menu/restaurants/barrancabermeja/maravillas-del-cafe', 'verificado_en_fuente', DATE '2026-10-15'),
  ('BCA-SEG-001', 'Río Magdalena: no apto para bañarse con niños', 'El nivel del río cambia de forma brusca. En febrero de 2026 hubo alerta amarilla por aumento del nivel y en agosto de 2026, por la sequía, la Oficina de Gestión del Riesgo pidió no caminar ni permanecer en los bancos de arena porque el río puede volver a subir y el terreno no es firme.', 'seguridad', 'Barrancabermeja', 'Santander', 'seguridad | río magdalena | bañarse | alerta | bancos de arena | zona:Río Magdalena | ninos:no | bano:no_recomendado | seguridad:No bañarse en el río ni subirse a los bancos de arena. Disfrutarlo desde el malecón o en lancha con chaleco.', 'sin_relacion', NULL, 'Blu Radio / Vanguardia', 'Advierten riesgo de transitar por bancos de arena en el río Magdalena por sequía', DATE '2026-08-26', 'https://www.bluradio.com/regiones/santanderes/advierten-riesgo-de-transitar-por-bancos-de-arena-en-el-rio-magdalena-en-barrancabermeja-rg10', 'alerta_vigente', DATE '2026-10-15')
